type AttrType='TEXT'|'NUMBER'|'BOOLEAN'|'SELECT'|'MULTISELECT'|'DATE';
type AttrDef={id:string;key:string;label:string;type:AttrType;unit:string|null;required:boolean;options:{value:string;label:string}[]};
type Draft={id:string;title:string|null;description:string|null;priceMinor:number|null;currency:string;city:string|null;postalCode:string|null;category:{id:string;name:string;slug:string;domain:string};attributes:{attributeId:string;key:string;value:unknown}[];vehicle?:Record<string,unknown>|null;histovecUrl?:string|null;property?:Record<string,unknown>|null;energy?:Record<string,unknown>|null};
type Commerce={listing:{priceMinor:number|null;currency:string;domain:string;isVacation:boolean};settings:{acceptsOffers:boolean;securePaymentEnabled:boolean;commissionPayer:'SELLER'|'BUYER';handDeliveryEnabled:boolean;mondialRelayEnabled:boolean;colissimoEnabled:boolean;packageWeightG:number|null;packageLengthCm:number|null;packageWidthCm:number|null;packageHeightCm:number|null};sellerPaymentReady:boolean};
type Check={ready:boolean;phoneVerified?:boolean;phoneVerificationRequired?:boolean;sellerKind?:'PARTICULIER'|'PROFESSIONNEL';errors:string[];warnings:string[];quality:{score:number;level:string;issues:{code:string;label:string;severity:string;step?:number}[]};summary:{mediaCount:number;category:{name:string;domain:string};title?:string|null;description?:string|null;priceMinor?:number|null;currency?:string;city?:string|null;postalCode?:string|null;coverUrl?:string|null;isVacation?:boolean};compliance?:{consumerDisclosure?:{sellerIsTrader:boolean;withdrawalRightApplies:boolean|null;withdrawalPeriodDays:number|null;withdrawalExceptionCode:string|null}|null};issues?:{errors:{code:string;step:number}[];warnings:{code:string;step:number}[]};edit?:{isolated:boolean;originalListingId:string;previousStatus:string}|null};
type PublishResult={status:'PENDING'|'PUBLISHED';listing:{slug:string|null};moderation:{required:boolean;autoApproval:{scheduled:boolean;eligibleAt?:string;delaySeconds?:number}}};
type PropertyState={transactionType:'SALE'|'RENTAL';propertyType:string;surfaceM2:string;rooms:string;bedrooms:string;furnished:boolean;floor:string;totalFloors:string;landM2:string};
type EnergyState={isExempt:boolean;exemptionReason:string;dpeNumber:string;dpeDate:string;energyClass:string;climateClass:string;consumption:string;ghg:string;annualMin:string;annualMax:string;referenceYears:string};
type CitySuggestion={name?:string;city?:string};
type PublishLocalDraft={phase:2|3|4;values:Record<string,unknown>;description:string;postalCode:string;city:string;price:string;property:PropertyState;energy:EnergyState;commerceSettings?:Commerce['settings']};

const dedicatedRealEstate=new Set(['propertyType','surface','rooms','bedrooms','floor','furnished','dpe','ges']);
const issueLabels:Record<string,string>={title_required:'Titre obligatoire',description_required:'Description obligatoire',city_required:'Ville obligatoire',postal_code_required:'Code postal obligatoire',price_required:'Prix obligatoire',monthly_rent_required:'Loyer mensuel obligatoire',hourly_rate_required:'Tarif horaire obligatoire',ready_photo_required:'Ajoutez au moins une photo',vehicle_details_required:'Informations du véhicule incomplètes',property_details_required:'Informations du bien incomplètes',energy_performance_required:'DPE / performance énergétique obligatoire',dpe_number_required:'Numéro DPE obligatoire',valid_dpe_date_required:'Date DPE invalide',energy_class_required:'Classe énergie obligatoire',climate_class_required:'Classe climat obligatoire',annual_energy_cost_required:'Coût énergétique annuel obligatoire',energy_price_reference_years_required:'Années de référence énergie obligatoires',dpe_exemption_reason_required:'Motif d’exemption DPE obligatoire',package_weight_required:'Poids du colis obligatoire'};
function numberValue(v:unknown){const raw=String(v??'').trim().replace(',','.');if(!raw)return null;const n=Number(raw);return Number.isFinite(n)?n:null}
function optionalNumber(v:string){const n=numberValue(v);return n===null?null:n}
function optionalInteger(v:unknown){const n=numberValue(v);return n===null?null:Math.round(n)}
function eurosToMinor(v:string){const n=numberValue(v);return n===null?null:Math.round(n*100)}
function emptyValue(def:AttrDef,v:unknown){return v===undefined||v===null||v===''||(def.type==='MULTISELECT'&&Array.isArray(v)&&v.length===0)}
function byKey(defs:AttrDef[],values:Record<string,unknown>,key:string){const d=defs.find(x=>x.key===key);return d?values[d.id]:undefined}

export default function PublishScreen(){
  const{id,step:stepParam}=useLocalSearchParams<{id:string;step?:string}>();const{token,user,loading:authLoading}=useAuth();
  const initial=Number(stepParam);const[phase,setPhase]=useState<2|3|4>(initial===3?3:initial===4?4:2);const[anim]=useState(()=>new Animated.Value(0));const[shift]=useState(()=>new Animated.Value(18));
  const[draft,setDraft]=useState<Draft|null>(null);const[defs,setDefs]=useState<AttrDef[]>([]);const[values,setValues]=useState<Record<string,unknown>>({});const[commerce,setCommerce]=useState<Commerce|null>(null);const[loading,setLoading]=useState(true);const[saving,setSaving]=useState(false);const[publishing,setPublishing]=useState(false);const[check,setCheck]=useState<Check|null>(null);const[flash,setFlash]=useState<{ok:boolean;text:string}|null>(null);const[selectDef,setSelectDef]=useState<AttrDef|null>(null);const[optionQuery,setOptionQuery]=useState('');const[consents,setConsents]=useState({terms:false,rules:false,accuracy:false,pro:false});const[result,setResult]=useState<PublishResult|null>(null);const[plate,setPlate]=useState('');const[plateBusy,setPlateBusy]=useState(false);const[plateMessage,setPlateMessage]=useState('');const[histovecUrl,setHistovecUrl]=useState('');const[localDraftHydrated,setLocalDraftHydrated]=useState(false);
  const[description,setDescription]=useState('');const[postalCode,setPostalCode]=useState('');const[city,setCity]=useState('');const[returnMode,setReturnMode]=useState<''|'yes'|'no'>('');const[returnDays,setReturnDays]=useState('14');const[returnException,setReturnException]=useState('');const[cityOptions,setCityOptions]=useState<string[]>([]);const[cityLookup,setCityLookup]=useState<'idle'|'loading'|'done'|'error'>('idle');const[aiBusy,setAiBusy]=useState(false);const[price,setPrice]=useState('');
  const[property,setProperty]=useState<PropertyState>({transactionType:'SALE',propertyType:'Appartement',surfaceM2:'',rooms:'',bedrooms:'',furnished:false,floor:'',totalFloors:'',landM2:''});
  const[energy,setEnergy]=useState<EnergyState>({isExempt:false,exemptionReason:'',dpeNumber:'',dpeDate:'',energyClass:'',climateClass:'',consumption:'',ghg:'',annualMin:'',annualMax:'',referenceYears:''});

  useEffect(()=>{anim.setValue(0);shift.setValue(18);Animated.parallel([Animated.timing(anim,{toValue:1,duration:260,useNativeDriver:true}),Animated.timing(shift,{toValue:0,duration:260,useNativeDriver:true})]).start()},[phase,anim,shift]);
  const runCheck=useCallback(async(auth=token,listingId=String(id))=>{if(!auth)return null;try{const c=await apiRequest<Check>(`/listings/${encodeURIComponent(listingId)}/publication-check`,{token:auth});setCheck(c);return c}catch{return null}},[token,id]);
  const load=useCallback(async()=>{if(!token||!id)return;setLoading(true);try{const d=await apiRequest<{listing:Draft}>(`/listings/${encodeURIComponent(String(id))}/draft`,{token});const listing=d.listing;const[a,c]=await Promise.all([apiRequest<{category:{attributes:AttrDef[]}}>(`/categories/${encodeURIComponent(listing.category.slug)}/attributes`),apiRequest<Commerce>(`/listings/${encodeURIComponent(String(id))}/commerce-settings`,{token})]);setDraft(listing);setDescription(listing.description??'');setPostalCode(listing.postalCode??'');setCity(listing.city??'');setHistovecUrl(listing.histovecUrl??'');setDefs(a.category.attributes??[]);setCommerce(c);setPrice(c.listing.priceMinor==null?'':String(c.listing.priceMinor/100).replace('.',','));const initialValues:Record<string,unknown>={};for(const item of listing.attributes??[])initialValues[item.attributeId]=item.value;setValues(initialValues);const p=listing.property as any;if(p)setProperty({transactionType:p.transactionType??'SALE',propertyType:p.propertyType??'Appartement',surfaceM2:String(p.surfaceM2??''),rooms:String(p.rooms??''),bedrooms:String(p.bedrooms??''),furnished:Boolean(p.furnished),floor:String(p.floor??''),totalFloors:String(p.totalFloors??''),landM2:String(p.landM2??'')});const e=listing.energy as any;if(e)setEnergy({isExempt:Boolean(e.isExempt),exemptionReason:e.exemptionReason??'',dpeNumber:e.dpeNumber??'',dpeDate:e.dpeDate?String(e.dpeDate).slice(0,10):'',energyClass:e.energyClass??'',climateClass:e.climateClass??'',consumption:String(e.energyConsumptionKwhM2Year??''),ghg:String(e.ghgKgCo2M2Year??''),annualMin:e.annualCostMinMinor!=null?String(Number(e.annualCostMinMinor)/100):'',annualMax:e.annualCostMaxMinor!=null?String(Number(e.annualCostMaxMinor)/100):'',referenceYears:e.energyPriceReferenceYears??''});await runCheck(token,String(id))}catch(e){if(e instanceof ApiError&&e.status===401)router.replace('/auth/login');else setFlash({ok:false,text:'Impossible de charger la préparation de publication.'})}finally{setLoading(false)}},[token,id,runCheck]);
  useEffect(()=>{void load()},[load]);
  useEffect(()=>{if(!user?.id||!id||loading||!draft||!commerce||localDraftHydrated)return;let active=true;const key=localDraftKey('publish',user.id,String(id));void readLocalDraft<PublishLocalDraft>(key).then(saved=>{if(!active||!saved)return;setPhase(saved.phase);setValues(saved.values??{});setDescription(saved.description??'');setPostalCode(saved.postalCode??'');setCity(saved.city??'');setPrice(saved.price??'');setProperty(saved.property);setEnergy(saved.energy);if(saved.commerceSettings)setCommerce(current=>current?{...current,settings:{...current.settings,...saved.commerceSettings!}}:current);setFlash({ok:true,text:'Vos modifications locales ont été restaurées.'})}).finally(()=>{if(active)setLocalDraftHydrated(true)});return()=>{active=false}},[user?.id,id,loading,draft,commerce,localDraftHydrated]);
  useEffect(()=>{if(!user?.id||!id||!draft||!commerce||!localDraftHydrated||result)return;const key=localDraftKey('publish',user.id,String(id));const timer=setTimeout(()=>{const snapshot:PublishLocalDraft={phase,values,description,postalCode,city,price,property,energy,commerceSettings:commerce.settings};void writeLocalDraft(key,snapshot)},450);return()=>clearTimeout(timer)},[user?.id,id,draft,commerce,localDraftHydrated,result,phase,values,description,postalCode,city,price,property,energy]);
  useEffect(()=>{if(postalCode.length!==5||!/^[0-9]{5}$/.test(postalCode)){setCityLookup('idle');setCityOptions([]);return}const timer=setTimeout(()=>{setCityLookup('loading');apiRequest<{cities:CitySuggestion[]}>(`/locations/postal-code/${postalCode}`).then(p=>{const names=[...new Set((p.cities??[]).map(x=>String(x.name??x.city??'').trim()).filter(Boolean))];setCityOptions(names);if(names.length===1)setCity(names[0]);setCityLookup('done')}).catch(()=>{setCityOptions([]);setCityLookup('error')})},250);return()=>clearTimeout(timer)},[postalCode]);

  const visibleDefs=useMemo(()=>draft?.category.domain==='REAL_ESTATE'?defs.filter(d=>!dedicatedRealEstate.has(d.key)):defs,[defs,draft]);const allConsents=consents.terms&&consents.rules&&consents.accuracy&&consents.pro;
  const proProduct=Boolean(user?.kind==='PROFESSIONNEL'&&!check?.summary?.isVacation&&draft?.priceMinor!==null&&draft?.priceMinor!==undefined&&!['JOB','SERVICE','REAL_ESTATE','VEHICLE'].includes(draft?.category.domain??''));
  const returnPolicyReady=!proProduct||(returnMode==='yes'&&Number.isInteger(Number(returnDays))&&Number(returnDays)>0)||(returnMode==='no'&&returnException.trim().length>=3);
  useEffect(()=>{const d=check?.compliance?.consumerDisclosure;if(!d||returnMode!=='')return;setReturnMode(d.withdrawalRightApplies===true?'yes':d.withdrawalRightApplies===false?'no':'');if(d.withdrawalPeriodDays!=null)setReturnDays(String(d.withdrawalPeriodDays));if(d.withdrawalExceptionCode)setReturnException(d.withdrawalExceptionCode)},[check?.compliance?.consumerDisclosure,returnMode]);
  useEffect(()=>{if(phase!==2||!token||!draft||loading)return;const timer=setTimeout(()=>{const attributes=visibleDefs.map(def=>{const raw=values[def.id];if(emptyValue(def,raw))return{attributeId:def.id,value:null};if(def.type==='NUMBER')return{attributeId:def.id,value:numberValue(raw)};if(def.type==='BOOLEAN')return{attributeId:def.id,value:Boolean(raw)};return{attributeId:def.id,value:raw}});void apiRequest(`/listings/${encodeURIComponent(draft.id)}/autosave`,{method:'PATCH',token,body:{description,city,postalCode,attributes}}).catch(()=>undefined)},850);return()=>clearTimeout(timer)},[phase,token,draft,loading,visibleDefs,values,description,city,postalCode]);
  function setAttr(def:AttrDef,value:unknown){setValues(v=>({...v,[def.id]:value}));setCheck(null)}
  function go(next:2|3|4){setFlash(null);setPhase(next)}

  async function lookupPlate(){if(!token||!draft||draft.category.domain!=='VEHICLE'||plateBusy||plate.trim().length<5)return;const normalized=plate.toUpperCase().replace(/[^A-Z0-9]/g,'');const formatted=normalized.length===7?`${normalized.slice(0,2)}-${normalized.slice(2,5)}-${normalized.slice(5)}`:plate.toUpperCase();setPlate(formatted);setPlateBusy(true);setPlateMessage('Identification du véhicule…');try{const p=await apiRequest<{vehicle?:Record<string,unknown>;wizardAttributes?:Record<string,unknown>}>(`/listings/${encodeURIComponent(draft.id)}/vehicle/from-plate`,{method:'POST',token,body:{registrationPlate:formatted}});const v=p.vehicle??{};const map:Record<string,unknown>={...(p.wizardAttributes??{}),brand:v.make,model:v.model,version:v.version,firstRegistration:typeof v.firstRegistrationDate==='string'?v.firstRegistrationDate.slice(0,10):undefined,modelYear:v.modelYear,mileage:v.mileageKm,fuel:v.fuel,gearbox:v.transmission,fiscalPower:v.fiscalPowerCv,powerKw:v.powerKw,doors:v.doors!=null?String(v.doors):undefined,seats:v.seats,color:v.color,bodyStyle:v.bodyType};setValues(current=>{const next={...current};for(const def of defs){const value=map[def.key];if(value!==undefined&&value!==null&&value!=='')next[def.id]=value}return next});setPlateMessage('Véhicule identifié. Vérifiez les informations préremplies.')}catch(e){const code=e instanceof ApiError?e.code:'';setPlateMessage(code==='vehicle_not_found'?'Aucun véhicule trouvé pour cette plaque.':code==='invalid_registration_plate'||code==='invalid_request'?'Format de plaque invalide. Exemple : AB-123-CD.':'Service plaque momentanément indisponible. Vous pouvez remplir les champs manuellement.')}finally{setPlateBusy(false)}}

  async function generateDescription(){if(!token||!draft)return;setAiBusy(true);setFlash(null);try{const attributes=visibleDefs.map(a=>({label:a.label,value:values[a.id]})).filter(x=>x.value!==undefined&&x.value!==''&&x.value!==null&&!Array.isArray(x.value)).map(x=>({label:x.label,value:x.value as string|number|boolean}));const r=await apiRequest<{description:string;mode:string}>('/listings/ai-description',{method:'POST',token,body:{categoryId:draft.category.id,title:draft.title??'Annonce',attributes}});setDescription(r.description);setFlash({ok:true,text:r.mode==='ai'?'Description générée avec l’IA. Relisez-la avant de continuer.':'Description proposée à partir de vos informations.'})}catch{setFlash({ok:false,text:'La description assistée n’est pas disponible pour le moment.'})}finally{setAiBusy(false)}}

  async function saveDetails(){if(!token||!draft)return false;if(description.trim().length<20){setFlash({ok:false,text:'La description doit contenir au moins 20 caractères.'});return false}if(!/^[0-9]{5}$/.test(postalCode)||city.trim().length<2){setFlash({ok:false,text:'Indiquez un code postal et une ville valides.'});return false}const missing=visibleDefs.filter(def=>def.required&&emptyValue(def,values[def.id]));if(missing.length){setFlash({ok:false,text:`Champ obligatoire : ${missing[0].label}`});return false}setSaving(true);setFlash(null);try{const payload=visibleDefs.flatMap(def=>{const raw=values[def.id];if(emptyValue(def,raw))return[];if(def.type==='NUMBER'){const n=numberValue(raw);if(n===null)return[];return[{attributeId:def.id,value:n}]}if(def.type==='BOOLEAN')return[{attributeId:def.id,value:Boolean(raw)}];return[{attributeId:def.id,value:raw}]});await apiRequest(`/listings/${encodeURIComponent(draft.id)}/basics`,{method:'PATCH',token,body:{description:description.trim(),postalCode,city:city.trim()}});await apiRequest(`/listings/${encodeURIComponent(draft.id)}/attributes`,{method:'PUT',token,body:{values:payload}});
      if(draft.category.domain==='VEHICLE'){const vehicle={make:byKey(defs,values,'brand')||null,model:byKey(defs,values,'model')||null,version:byKey(defs,values,'version')||null,firstRegistrationDate:byKey(defs,values,'firstRegistration')||null,modelYear:optionalInteger(byKey(defs,values,'modelYear')??byKey(defs,values,'year')),fuel:byKey(defs,values,'fuel')||null,transmission:byKey(defs,values,'gearbox')||null,bodyType:byKey(defs,values,'bodyStyle')||null,powerKw:optionalInteger(byKey(defs,values,'powerKw')),fiscalPowerCv:optionalInteger(byKey(defs,values,'fiscalPower')),seats:optionalInteger(byKey(defs,values,'seats')),doors:optionalInteger(byKey(defs,values,'doors')),color:byKey(defs,values,'color')||null,mileageKm:optionalInteger(byKey(defs,values,'mileage'))};await apiRequest(`/listings/${encodeURIComponent(draft.id)}/vehicle`,{method:'PUT',token,body:vehicle});await apiRequest(`/listings/${encodeURIComponent(draft.id)}/vehicle/histovec`,{method:'PUT',token,body:{url:histovecUrl.trim()||null}})}
      if(draft.category.domain==='REAL_ESTATE'){const surface=numberValue(property.surfaceM2);if(surface===null||surface<=0||property.propertyType.trim().length<2){setFlash({ok:false,text:'Type de bien et surface sont obligatoires.'});return false}const propertyPayload={transactionType:property.transactionType,propertyType:property.propertyType.trim(),surfaceM2:surface,rooms:optionalNumber(property.rooms),bedrooms:optionalNumber(property.bedrooms),furnished:property.furnished,floor:optionalNumber(property.floor),totalFloors:optionalNumber(property.totalFloors),landM2:optionalNumber(property.landM2),postalCode,city:city.trim(),countryCode:'FR'};let energyPayload:any;if(energy.isExempt){if(energy.exemptionReason.trim().length<5){setFlash({ok:false,text:'Indiquez le motif d’exemption DPE.'});return false}energyPayload={isExempt:true,exemptionReason:energy.exemptionReason.trim()}}else{const min=eurosToMinor(energy.annualMin),max=eurosToMinor(energy.annualMax),cons=numberValue(energy.consumption),ghg=numberValue(energy.ghg);if(!energy.dpeNumber||!/^\d{4}-\d{2}-\d{2}$/.test(energy.dpeDate)||!energy.energyClass||!energy.climateClass||min===null||max===null||cons===null||ghg===null||!energy.referenceYears.trim()){setFlash({ok:false,text:'Complétez toutes les informations DPE obligatoires.'});return false}energyPayload={isExempt:false,dpeNumber:energy.dpeNumber.trim(),dpeDate:energy.dpeDate,energyClass:energy.energyClass,climateClass:energy.climateClass,energyConsumptionKwhM2Year:cons,ghgKgCo2M2Year:ghg,annualCostMinMinor:min,annualCostMaxMinor:max,energyPriceReferenceYears:energy.referenceYears.trim()}}await apiRequest(`/listings/${encodeURIComponent(draft.id)}/property-energy`,{method:'PUT',token,body:{property:propertyPayload,energy:energyPayload}})}
      const confirmed=await apiRequest<{listing:Draft}>(`/listings/${encodeURIComponent(draft.id)}/draft`,{token});const saved=confirmed.listing;if((saved.description??'').trim()!==description.trim()||(saved.postalCode??'').trim()!==postalCode.trim()||(saved.city??'').trim().toLocaleLowerCase('fr-FR')!==city.trim().toLocaleLowerCase('fr-FR'))throw new Error('details_not_persisted');const restoredValues:Record<string,unknown>={};for(const item of saved.attributes??[])restoredValues[item.attributeId]=item.value;setValues(restoredValues);setDraft({...draft,...saved,description:saved.description,postalCode:saved.postalCode,city:saved.city});setDescription(saved.description??'');setPostalCode(saved.postalCode??'');setCity(saved.city??'');await runCheck();go(3);return true
    }catch(e){const code=e instanceof ApiError?e.code:e instanceof Error?e.message:'';setFlash({ok:false,text:code==='invalid_histovec_url'?'Le lien HistoVec doit provenir du site officiel histovec.interieur.gouv.fr.':code==='listing_content_policy_violation'?'Le contenu contient un terme interdit ou des coordonnées directes.':code==='invalid_request'&&draft.category.domain==='VEHICLE'?'Une information véhicule n’est pas valide. Vérifiez les champs numériques et la date de première immatriculation.':code==='details_not_persisted'?'Les détails n’ont pas été confirmés par le serveur. Réessayez sans quitter cette étape.':'Impossible d’enregistrer les détails.'});return false}finally{setSaving(false)}}

  async function saveCommerce(){if(!token||!draft||!commerce)return false;const minor=eurosToMinor(price);if(minor===null||minor<0){setFlash({ok:false,text:'Indiquez un prix valide.'});return false}setSaving(true);setFlash(null);try{const s=commerce.settings;await apiRequest(`/listings/${encodeURIComponent(draft.id)}/basics`,{method:'PATCH',token,body:{priceMinor:minor,currency:'EUR'}});await apiRequest(`/listings/${encodeURIComponent(draft.id)}/commerce-settings`,{method:'PUT',token,body:{priceMinor:minor,acceptsOffers:s.acceptsOffers,securePaymentEnabled:s.securePaymentEnabled,commissionPayer:s.commissionPayer,handDeliveryEnabled:s.handDeliveryEnabled,mondialRelayEnabled:s.mondialRelayEnabled,colissimoEnabled:s.colissimoEnabled,packageWeightG:s.packageWeightG,packageLengthCm:s.packageLengthCm,packageWidthCm:s.packageWidthCm,packageHeightCm:s.packageHeightCm}});setDraft({...draft,priceMinor:minor,currency:'EUR'});await runCheck();go(4);return true}catch(e){const code=e instanceof ApiError?e.code:'';setFlash({ok:false,text:code==='package_weight_required'?'Indiquez le poids du colis.':code==='shipping_not_supported_for_category'?'La livraison n’est pas disponible pour cette catégorie.':'Impossible d’enregistrer le prix et la livraison.'});return false}finally{setSaving(false)}}

  async function publish(){if(!token||!draft||!allConsents)return;setPublishing(true);setFlash(null);try{const latest=await apiRequest<Check>(`/listings/${encodeURIComponent(draft.id)}/publication-check`,{token});setCheck(latest);if(!latest.ready){setFlash({ok:false,text:'Quelques informations sont encore nécessaires avant publication.'});return}const latestProProduct=Boolean(user?.kind==='PROFESSIONNEL'&&!latest.summary?.isVacation&&latest.summary?.priceMinor!==null&&latest.summary?.priceMinor!==undefined&&!['JOB','SERVICE','REAL_ESTATE','VEHICLE'].includes(latest.summary.category.domain));if(latestProProduct){if(!returnPolicyReady){setFlash({ok:false,text:'Indiquez la politique de retour réellement applicable à cette vente professionnelle.'});return}await apiRequest(`/listings/${encodeURIComponent(draft.id)}/consumer-disclosure`,{method:'PUT',token,body:{sellerIsTrader:true,withdrawalRightApplies:returnMode==='yes',withdrawalPeriodDays:returnMode==='yes'?Number(returnDays):undefined,withdrawalExceptionCode:returnMode==='no'?returnException.trim():undefined}})}const r=await apiRequest<PublishResult>(`/listings/${encodeURIComponent(draft.id)}/publish`,{method:'POST',token,body:{termsAccepted:true,rulesAccepted:true,accuracyConfirmed:true,professionalDisclosureConfirmed:true}});if(user?.id)await removeLocalDraft(localDraftKey('publish',user.id,String(draft.id)));setResult(r)}catch(e){const code=e instanceof ApiError?e.code:'';setFlash({ok:false,text:code==='listing_content_policy_violation'?'Publication bloquée : contenu interdit ou coordonnées directes détectées.':code==='publication_consents_required'?'Confirmez les quatre déclarations avant publication.':code==='consumer_return_policy_required'?'Complétez la politique de retour de cette annonce professionnelle avant publication.':code==='duplicate_listing_exists'?'Cette annonce existe déjà dans votre compte.':code==='account_security_hold'?'Votre compte nécessite une vérification de sécurité avant publication.':'Publication impossible pour le moment.'})}finally{setPublishing(false)}}

  if(authLoading||loading)return <SafeAreaView style={s.center}><ActivityIndicator color={PA.primary}/></SafeAreaView>;
  if(!user||!token||!draft||!commerce)return <SafeAreaView style={s.center}><Text style={s.error}>Cette préparation n’est pas disponible.</Text></SafeAreaView>;
  if(result){const live=result.status==='PUBLISHED';return <LinearGradient colors={['#f7f7fb','#ffffff']} style={s.doneGradient}><SafeAreaView style={s.safe}><ScrollView contentContainerStyle={s.donePage} keyboardShouldPersistTaps="handled" keyboardDismissMode="interactive" automaticallyAdjustKeyboardInsets><View style={s.doneCard}><View style={s.doneIcon}><AppIcon name="circle-check" size={38} color={PA.success}/></View><Text style={s.doneKicker}>PUBLICATION RÉUSSIE</Text><Text style={s.doneTitle}>Félicitations, votre annonce a bien été ajoutée !</Text><Text style={s.doneText}>{live?'Votre annonce est maintenant en ligne sur Petit Annonces.':'Votre annonce a été enregistrée et envoyée pour vérification. Vous pouvez suivre son statut depuis « Mes annonces ».'}</Text><View style={s.doneSteps}><View style={s.doneStep}><AppIcon name="check" size={14} color={PA.primary}/><View style={{flex:1}}><Text style={s.doneStepTitle}>Annonce enregistrée</Text><Text style={s.doneStepText}>Vos informations et photos ont bien été prises en compte.</Text></View></View><View style={s.doneStep}><AppIcon name="shield-halved" size={14} color={PA.primary}/><View style={{flex:1}}><Text style={s.doneStepTitle}>{live?'Annonce en ligne':'Vérification en cours'}</Text><Text style={s.doneStepText}>{live?'Elle peut maintenant être consultée par les acheteurs.':result.moderation.autoApproval?.scheduled?'Revérification automatique prévue dans 1 à 2 minutes.':'Notre contrôle protège la qualité et la sécurité de la plateforme.'}</Text></View></View></View><View style={s.doneActions}><Pressable style={[s.doneButton,s.donePrimary]} onPress={()=>router.replace('/my-listings')}><AppIcon name="list" size={13} color="#fff"/><Text style={s.donePrimaryText}>Mes annonces</Text></Pressable>{live&&result.listing.slug?<Pressable style={[s.doneButton,s.doneSecondary]} onPress={()=>router.replace(`/annonce/${result.listing.slug}` as never)}><AppIcon name="arrow-right" size={13} color="#5143d7"/><Text style={s.doneSecondaryText}>Voir mon annonce</Text></Pressable>:<Pressable style={[s.doneButton,s.doneSecondary]} onPress={()=>router.replace({pathname:'/sell',params:{direct:'1',fresh:String(Date.now())}} as never)}><AppIcon name="plus" size={13} color="#5143d7"/><Text style={s.doneSecondaryText}>Ajouter une autre</Text></Pressable>}</View></View></ScrollView></SafeAreaView></LinearGradient>}

  return <SafeAreaView style={s.safe} edges={['top']}><ScrollView contentContainerStyle={s.page} keyboardShouldPersistTaps="handled" keyboardDismissMode="interactive" automaticallyAdjustKeyboardInsets><View style={s.top}><Pressable accessibilityRole="button" accessibilityLabel="Étape précédente" style={s.back} onPress={()=>phase===2?router.back():go((phase-1) as 2|3)}><AppIcon name="arrow-left" size={15} color={PA.ink}/></Pressable><View style={{flex:1}}><Text style={s.eyebrow}>DÉPOSER UNE ANNONCE</Text><Text style={s.title} numberOfLines={1}>{draft.title||'Votre annonce'}</Text></View><View style={s.topMark}><AppIcon name={phase===2?'sliders':phase===3?'euro-sign':'shield-halved'} size={18}/></View></View><ListingWizardStepper current={phase}/>{flash?<View style={[s.flash,flash.ok?s.flashOk:s.flashErr]}><Text style={[s.flashText,flash.ok?s.okText:s.errText]}>{flash.text}</Text></View>:null}<Animated.View style={{opacity:anim,transform:[{translateX:shift}]}}>
    {phase===2?<><CardHead icon={draft.category.domain==='VEHICLE'?'car':'sliders'} kicker="Étape 3 sur 5" title="Détails de l’annonce" text="Complétez les informations utiles pour que les acheteurs comprennent immédiatement votre offre."/>{check?.edit?.isolated?<View style={s.editSafe}><AppIcon name="shield-halved" size={15} color="#285a9f"/><View style={{flex:1}}><Text style={s.editSafeTitle}>Modification sécurisée</Text><Text style={s.editSafeText}>L’annonce actuelle reste en ligne jusqu’à la validation finale.</Text></View></View>:null}{draft.category.domain==='VEHICLE'?<Card title="Identifier avec la plaque française" subtitle="Préremplissez automatiquement les caractéristiques disponibles." icon="car"><View style={s.plateRow}><View style={s.platePrefix}><Text style={s.platePrefixText}>FR</Text></View><TextInput style={[s.input,{flex:1,borderTopLeftRadius:0,borderBottomLeftRadius:0}]} value={plate} onChangeText={v=>{setPlate(v.toUpperCase().replace(/[^A-Z0-9-]/g,''));setPlateMessage('')}} autoCapitalize="characters" autoCorrect={false} placeholder="AB-123-CD" placeholderTextColor="#9999a7" maxLength={12}/><Pressable style={[s.plateButton,(plateBusy||plate.trim().length<5)&&s.disabled]} disabled={plateBusy||plate.trim().length<5} onPress={()=>void lookupPlate()}>{plateBusy?<ActivityIndicator size="small" color="#fff"/>:<AppIcon name="magnifying-glass" size={13} color="#fff"/>}</Pressable></View>{plateMessage?<Text style={s.vehicleHint}>{plateMessage}</Text>:null}<Text style={[s.label,{marginTop:14}]}>Lien HistoVec officiel · facultatif</Text><TextInput style={s.input} value={histovecUrl} onChangeText={setHistovecUrl} autoCapitalize="none" autoCorrect={false} keyboardType="url" placeholder="https://histovec.interieur.gouv.fr/..." placeholderTextColor="#9999a7"/></Card>:null}<Card title="Caractéristiques" subtitle={`${draft.category.name} · complétez les champs utiles`} icon="list-check"><View style={s.fields}>{visibleDefs.map(def=><AttributeField key={def.id} def={def} value={values[def.id]} setValue={v=>setAttr(def,v)} openSelect={()=>{setSelectDef(def);setOptionQuery('')}}/>)}{!visibleDefs.length?<Text style={s.muted}>Aucune caractéristique supplémentaire requise.</Text>:null}</View></Card>{draft.category.domain==='REAL_ESTATE'?<RealEstateCard property={property} setProperty={setProperty} energy={energy} setEnergy={setEnergy}/>:null}<Card title="Localisation de l’annonce" subtitle="La carte publique affiche une position approximative, jamais votre adresse personnelle." icon="location-dot"><View style={s.two}><MiniInput label="Code postal *" value={postalCode} set={v=>setPostalCode(v.replace(/\D/g,'').slice(0,5))}/><View style={s.mini}><Text style={s.label}>Ville *</Text>{cityOptions.length>1?<Pressable style={s.select} onPress={()=>{const next=cityOptions[(Math.max(0,cityOptions.indexOf(city))+1)%cityOptions.length];setCity(next)}}><Text style={s.selectText}>{city||'Choisir'}</Text><AppIcon name="chevron-down" size={12} color={PA.muted}/></Pressable>:<TextInput style={s.input} value={city} onChangeText={setCity} placeholder="Ville" placeholderTextColor="#9999a7"/>}<Text style={s.lookup}>{cityLookup==='loading'?'Recherche de la ville…':cityLookup==='error'?'Code postal introuvable':postalCode.length===5&&city?'Ville détectée':' '}</Text></View></View></Card><Card title="Description" subtitle="Conseillé : 80 mots minimum" icon="align-left"><Pressable style={s.aiButton} onPress={()=>void generateDescription()} disabled={aiBusy}><AppIcon name="wand-magic-sparkles" size={15} color={PA.primary}/><Text style={s.aiButtonText}>{aiBusy?'Génération…':'Remplir avec l’IA'}</Text></Pressable><View style={s.aiHint}><AppIcon name="sparkles" size={11} color={PA.primary}/><Text style={s.aiHintText}>L’assistant utilise uniquement les informations renseignées dans cette annonce.</Text></View><TextInput style={[s.input,s.textarea]} value={description} onChangeText={setDescription} placeholder="Décrivez l’état, les caractéristiques, les équipements et les informations utiles…" placeholderTextColor="#9999a7" multiline maxLength={12000}/><Text style={s.counter}>{description.length}/12000</Text></Card><WizardFooter previous={()=>router.back()} next={()=>void saveDetails()} busy={saving} nextText="Suivant : Prix"/></>:null}
    {phase===3?<><CardHead icon={commerce.listing.isVacation?'calendar-days':'euro-sign'} kicker="Étape 4 sur 5" title={commerce.listing.isVacation?'Tarif du séjour':'Prix & livraison'} text={commerce.listing.isVacation?'Indiquez votre prix par nuit.':'Définissez le prix et les modes de remise disponibles.'}/><Card title={priceLabel(draft,commerce,property)} subtitle="Le montant est affiché en euros (€)." icon="euro-sign"><View style={s.priceRow}><TextInput style={[s.input,{flex:1}]} value={price} onChangeText={v=>setPrice(v.replace(/[^0-9,. ]/g,''))} inputMode="decimal" placeholder="0,00" placeholderTextColor="#9999a7"/><View style={s.euroBox}><Text style={s.euroText}>€</Text></View></View></Card><CommerceCard commerce={commerce} setCommerce={setCommerce}/><WizardFooter previous={()=>go(2)} next={()=>void saveCommerce()} busy={saving} nextText="Vérifier l’annonce"/></>:null}
    {phase===4?<><CardHead icon="shield-halved" kicker="Étape 5 sur 5" title="Vérification & publication" text="Un dernier contrôle avant l’envoi en modération."/><Card title="Qualité de votre annonce" subtitle="Petit Annonces vérifie les éléments obligatoires et la qualité globale." icon="chart-line"><View style={s.scoreHead}><Text style={s.score}>{check?.quality.score??0}<Text style={s.scoreSmall}>/100</Text></Text><Text style={s.quality}>{check?.quality.level??'À vérifier'}</Text></View><View style={s.scoreBar}><View style={[s.scoreFill,{width:`${Math.min(100,Math.max(0,check?.quality.score??0))}%`}]} /></View>{check?.errors.length?<View style={s.issueBox}>{check.errors.map(code=><View key={code} style={s.issueRow}><AppIcon name="circle-exclamation" size={12} color={PA.danger}/><Text style={s.issue}>{code.startsWith('required_attribute:')?`Champ obligatoire : ${code.split(':')[1]}`:issueLabels[code]??code}</Text></View>)}</View>:<View style={s.readyRow}><AppIcon name="circle-check" size={14} color={PA.success}/><Text style={s.ready}>Les contrôles obligatoires sont validés.</Text></View>}</Card>{check?.phoneVerificationRequired?<Card title="Téléphone à vérifier" subtitle="Sécurité du compte" icon="phone"><Text style={s.muted}>Un numéro de téléphone vérifié est requis pour publier une annonce et limiter les comptes frauduleux.</Text><Pressable style={s.secondary} onPress={()=>router.push('/security')}><Text style={s.secondaryText}>Vérifier mon téléphone</Text></Pressable></Card>:null}<Card title="Aperçu avant publication" subtitle={draft.category.name} icon="image"><Text style={s.previewTitle}>{draft.title}</Text><Text style={s.previewPrice}>{draft.priceMinor!=null?`${(draft.priceMinor/100).toLocaleString('fr-FR')} €`:'Prix à vérifier'}</Text><Text style={s.previewMeta}>{[draft.postalCode,draft.city].filter(Boolean).join(' ')}</Text><Text style={s.previewText} numberOfLines={5}>{draft.description}</Text></Card>{proProduct?<Card title="Politique de retour" subtitle="Obligatoire pour une vente professionnelle" icon="rotate-left"><Text style={s.muted}>Indiquez la politique réellement applicable à cette vente. Petit Annonces ne choisit pas cette information à votre place.</Text><View style={[s.chips,{marginTop:12}]}><Chip text="Rétractation applicable" active={returnMode==='yes'} onPress={()=>setReturnMode('yes')}/><Chip text="Retour non applicable / exception" active={returnMode==='no'} onPress={()=>setReturnMode('no')}/></View>{returnMode==='yes'?<MiniInput label="Délai de rétractation / retour (jours) *" value={returnDays} set={v=>setReturnDays(v.replace(/[^0-9]/g,'').slice(0,3))}/>:null}{returnMode==='no'?<View style={s.mini}><Text style={s.label}>Motif / exception *</Text><TextInput style={s.input} value={returnException} onChangeText={setReturnException} maxLength={120} placeholder="Ex. exception applicable au produit…" placeholderTextColor="#9999a7"/></View>:null}{!returnPolicyReady?<Text style={s.issue}>Complétez cette politique avant de publier l’annonce professionnelle.</Text>:null}</Card>:null}<Card title="Dernières confirmations" subtitle="Ces validations sont nécessaires avant la mise en ligne." icon="circle-check"><Consent checked={consents.terms} set={v=>setConsents(x=>({...x,terms:v}))} text="J’accepte les Conditions générales d’utilisation."/><Consent checked={consents.rules} set={v=>setConsents(x=>({...x,rules:v}))} text="Je respecte les règles de publication et les produits interdits."/><Consent checked={consents.accuracy} set={v=>setConsents(x=>({...x,accuracy:v}))} text="Les informations, le prix et les photos décrivent fidèlement l’annonce."/><Consent checked={consents.pro} set={v=>setConsents(x=>({...x,pro:v}))} text="Mon statut particulier ou professionnel est correctement indiqué."/></Card><Pressable style={[s.publish,(!allConsents||publishing||!check?.ready||!returnPolicyReady)&&s.disabled]} disabled={!allConsents||publishing||!check?.ready||!returnPolicyReady} onPress={()=>void publish()}>{publishing?<ActivityIndicator color="#fff"/>:<><AppIcon name="paper-plane" size={14} color="#fff"/><Text style={s.publishText}>{check?.edit?.isolated?'Valider les modifications':'Publier mon annonce'}</Text></>}</Pressable><Pressable style={s.previousFull} onPress={()=>go(3)}><AppIcon name="arrow-left" size={13} color={PA.muted}/><Text style={s.previousFullText}>Précédent : Prix</Text></Pressable></>:null}
  </Animated.View></ScrollView><OptionModal def={selectDef} value={selectDef?values[selectDef.id]:undefined} query={optionQuery} setQuery={setOptionQuery} close={()=>setSelectDef(null)} choose={value=>{if(!selectDef)return;if(selectDef.type==='MULTISELECT'){const current=Array.isArray(values[selectDef.id])?values[selectDef.id] as string[]:[];setAttr(selectDef,current.includes(value)?current.filter(x=>x!==value):[...current,value])}else{setAttr(selectDef,value);setSelectDef(null)}}}/></SafeAreaView>
}

function priceLabel(draft:Draft,commerce:Commerce,property:PropertyState){if(commerce.listing.isVacation)return'Prix par nuit';if(draft.category.domain==='JOB')return'Tarif horaire';if(draft.category.domain==='REAL_ESTATE'&&property.transactionType==='RENTAL')return'Loyer mensuel';return'Prix de l’annonce'}
function CardHead({icon,kicker,title,text}:{icon:any;kicker:string;title:string;text:string}){return <View style={s.cardHead}><View style={{flex:1}}><Text style={s.kicker}>{kicker}</Text><Text style={s.cardHeadTitle}>{title}</Text><Text style={s.cardHeadText}>{text}</Text></View><View style={s.headIcon}><AppIcon name={icon} size={19}/></View></View>}
function WizardFooter({previous,next,busy,nextText}:{previous:()=>void;next:()=>void;busy:boolean;nextText:string}){return <View style={s.wizardFooter}><Pressable style={s.footerSecondary} disabled={busy} onPress={previous}><AppIcon name="arrow-left" size={13} color={PA.muted}/><Text style={s.footerSecondaryText}>Précédent</Text></Pressable><Pressable style={[s.footerPrimary,busy&&s.disabled]} disabled={busy} onPress={next}>{busy?<ActivityIndicator size="small" color="#fff"/>:<><Text style={s.footerPrimaryText}>{nextText}</Text><AppIcon name="arrow-right" size={13} color="#fff"/></>}</Pressable></View>}
function AttributeField({def,value,setValue,openSelect}:{def:AttrDef;value:unknown;setValue:(v:unknown)=>void;openSelect:()=>void}){if(def.type==='BOOLEAN')return <View style={s.fieldRow}><View style={{flex:1}}><Text style={s.label}>{def.label}{def.required?' *':''}</Text>{def.unit?<Text style={s.help}>{def.unit}</Text>:null}</View><Switch value={Boolean(value)} onValueChange={setValue} trackColor={{true:PA.primary}}/></View>;if(def.type==='SELECT'||def.type==='MULTISELECT'){const selected=Array.isArray(value)?value.map(v=>def.options.find(o=>o.value===v)?.label??v).join(', '):def.options.find(o=>o.value===value)?.label??String(value??'');return <View style={s.field}><Text style={s.label}>{def.label}{def.required?' *':''}</Text><Pressable style={s.select} onPress={openSelect}><Text style={[s.selectText,!selected&&s.placeholder]} numberOfLines={2}>{selected||'Choisir'}</Text><AppIcon name="chevron-right" size={12} color={PA.muted}/></Pressable></View>}return <View style={s.field}><Text style={s.label}>{def.label}{def.required?' *':''}{def.unit?` · ${def.unit}`:''}</Text><TextInput style={s.input} value={String(value??'')} onChangeText={v=>setValue(v)} placeholder={def.type==='DATE'?'AAAA-MM-JJ':def.type==='NUMBER'?'0':'Saisir une valeur'} placeholderTextColor="#9999a7" inputMode={def.type==='NUMBER'?'decimal':'text'} maxLength={def.type==='TEXT'?1000:120}/></View>}
function CommerceCard({commerce,setCommerce}:{commerce:Commerce;setCommerce:(v:Commerce)=>void}){const s0=commerce.settings;const domain=commerce.listing.domain;const vacation=commerce.listing.isVacation;const secureAllowed=!vacation&&!['VEHICLE','REAL_ESTATE'].includes(domain);const shippable=!vacation&&!['VEHICLE','REAL_ESTATE','JOB','SERVICE'].includes(domain);function patch<K extends keyof Commerce['settings']>(k:K,v:Commerce['settings'][K]){setCommerce({...commerce,settings:{...s0,[k]:v}})}return <Card title="Paiement & livraison" subtitle="Choisissez les options proposées à l’acheteur." icon="truck-fast">{!vacation?<Toggle title="Accepter les offres" text="Les acheteurs peuvent proposer un autre prix." value={s0.acceptsOffers} set={v=>patch('acceptsOffers',v)} icon="handshake"/>:null}{secureAllowed?<Toggle title="Paiement sécurisé" text={commerce.sellerPaymentReady?'Paiement protégé disponible.':'Vous pourrez compléter votre IBAN avant le versement.'} value={s0.securePaymentEnabled} set={v=>patch('securePaymentEnabled',v)} icon="shield-halved"/>:null}{!vacation?<Toggle title="Remise en main propre" text="Remise directe entre acheteur et vendeur." value={s0.handDeliveryEnabled} set={v=>patch('handDeliveryEnabled',v)} icon="people-arrows"/>:null}{shippable?<><Toggle title="Mondial Relay" text="Expédition en point relais." value={s0.mondialRelayEnabled} set={v=>patch('mondialRelayEnabled',v)} icon="box"/><Toggle title="Colissimo" text="Expédition avec La Poste." value={s0.colissimoEnabled} set={v=>patch('colissimoEnabled',v)} icon="truck"/>{s0.mondialRelayEnabled||s0.colissimoEnabled?<MiniInput label="Poids du colis · grammes *" value={s0.packageWeightG?String(s0.packageWeightG):''} set={v=>patch('packageWeightG',optionalNumber(v))}/>:null}</>:null}{vacation?<Text style={s.muted}>Les réservations Vacances utilisent leur propre acompte et leur propre calendrier.</Text>:null}</Card>}
function RealEstateCard({property,setProperty,energy,setEnergy}:{property:PropertyState;setProperty:(v:PropertyState)=>void;energy:EnergyState;setEnergy:(v:EnergyState)=>void}){const classes=['A','B','C','D','E','F','G'];const pp=<K extends keyof PropertyState>(k:K,v:PropertyState[K])=>setProperty({...property,[k]:v});const ee=<K extends keyof EnergyState>(k:K,v:EnergyState[K])=>setEnergy({...energy,[k]:v});return <Card title="Bien immobilier" subtitle="Complétez les informations spécifiques du bien et du DPE." icon="building"><Text style={s.label}>Transaction *</Text><View style={s.chips}><Chip text="Vente" active={property.transactionType==='SALE'} onPress={()=>pp('transactionType','SALE')}/><Chip text="Location" active={property.transactionType==='RENTAL'} onPress={()=>pp('transactionType','RENTAL')}/></View><Text style={s.label}>Type de bien *</Text><View style={s.chips}>{['Appartement','Maison','Terrain','Local commercial'].map(v=><Chip key={v} text={v} active={property.propertyType===v} onPress={()=>pp('propertyType',v)}/>)}</View><View style={s.two}><MiniInput label="Surface m² *" value={property.surfaceM2} set={v=>pp('surfaceM2',v)}/><MiniInput label="Pièces" value={property.rooms} set={v=>pp('rooms',v)}/></View><View style={s.two}><MiniInput label="Chambres" value={property.bedrooms} set={v=>pp('bedrooms',v)}/><MiniInput label="Étage" value={property.floor} set={v=>pp('floor',v)}/></View><Toggle title="Meublé" text="Le bien est proposé meublé." value={property.furnished} set={v=>pp('furnished',v)} icon="couch"/><View style={s.divider}/><Toggle title="Bien exempté de DPE" text="Activez seulement si une exemption légale s’applique." value={energy.isExempt} set={v=>ee('isExempt',v)} icon="leaf"/>{energy.isExempt?<MiniInput label="Motif d’exemption *" value={energy.exemptionReason} set={v=>ee('exemptionReason',v)} numeric={false}/>:<><MiniInput label="Numéro DPE *" value={energy.dpeNumber} set={v=>ee('dpeNumber',v)} numeric={false}/><MiniInput label="Date DPE · AAAA-MM-JJ *" value={energy.dpeDate} set={v=>ee('dpeDate',v)} numeric={false}/><Text style={s.label}>Classe énergie *</Text><View style={s.chips}>{classes.map(v=><Chip key={v} text={v} active={energy.energyClass===v} onPress={()=>ee('energyClass',v)}/>)}</View><Text style={s.label}>Classe climat *</Text><View style={s.chips}>{classes.map(v=><Chip key={v} text={v} active={energy.climateClass===v} onPress={()=>ee('climateClass',v)}/>)}</View><View style={s.two}><MiniInput label="kWh/m²/an *" value={energy.consumption} set={v=>ee('consumption',v)}/><MiniInput label="kg CO₂/m²/an *" value={energy.ghg} set={v=>ee('ghg',v)}/></View><View style={s.two}><MiniInput label="Coût min €/an *" value={energy.annualMin} set={v=>ee('annualMin',v)}/><MiniInput label="Coût max €/an *" value={energy.annualMax} set={v=>ee('annualMax',v)}/></View><MiniInput label="Années de référence *" value={energy.referenceYears} set={v=>ee('referenceYears',v)} numeric={false}/></>}</Card>}
function Toggle({title,text,value,set,icon}:{title:string;text:string;value:boolean;set:(v:boolean)=>void;icon:any}){return <View style={s.toggle}><View style={s.toggleIcon}><AppIcon name={icon} size={16}/></View><View style={{flex:1}}><Text style={s.toggleTitle}>{title}</Text><Text style={s.toggleText}>{text}</Text></View><Switch value={value} onValueChange={set} trackColor={{true:PA.primary}}/></View>}
function MiniInput({label,value,set,numeric=true}:{label:string;value:string;set:(v:string)=>void;numeric?:boolean}){return <View style={s.mini}><Text style={s.label}>{label}</Text><TextInput style={s.input} value={value} onChangeText={set} inputMode={numeric?'decimal':'text'} placeholder="—" placeholderTextColor="#9999a7"/></View>}
function Chip({text,active,onPress}:{text:string;active:boolean;onPress:()=>void}){return <Pressable onPress={onPress} style={[s.chip,active&&s.chipActive]}><Text style={[s.chipText,active&&s.chipTextActive]}>{text}</Text></Pressable>}
function Consent({checked,set,text}:{checked:boolean;set:(v:boolean)=>void;text:string}){return <Pressable accessibilityRole="checkbox" accessibilityLabel={text} accessibilityState={{checked}} style={s.consent} onPress={()=>set(!checked)}><View accessible={false} style={[s.box,checked&&s.boxOn]}>{checked?<AppIcon name="check" size={12} color="#fff"/>:null}</View><Text style={s.consentText}>{text}</Text></Pressable>}
function Card({title,subtitle,icon,children}:{title:string;subtitle:string;icon:any;children:React.ReactNode}){return <View style={s.card}><View style={s.cardTitleRow}><View style={{flex:1}}><Text style={s.cardTitle}>{title}</Text><Text style={s.cardSub}>{subtitle}</Text></View><View style={s.smallIcon}><AppIcon name={icon} size={15}/></View></View><View style={{marginTop:14}}>{children}</View></View>}
function OptionModal({def,value,query,setQuery,close,choose}:{def:AttrDef|null;value:unknown;query:string;setQuery:(v:string)=>void;close:()=>void;choose:(v:string)=>void}){const selected=Array.isArray(value)?value as string[]:[];const items=useMemo(()=>{if(!def)return[];const q=query.toLocaleLowerCase('fr-FR').trim();return q?def.options.filter(o=>o.label.toLocaleLowerCase('fr-FR').includes(q)):def.options},[def,query]);return <Modal visible={Boolean(def)} animationType="slide" presentationStyle="pageSheet" onRequestClose={close}><SafeAreaView style={s.modal}><View style={s.modalHead}><View><Text style={s.eyebrow}>CHOIX</Text><Text style={s.modalTitle}>{def?.label}</Text></View><Pressable accessibilityRole="button" accessibilityLabel="Fermer la liste des choix" style={s.close} onPress={close}><AppIcon name="xmark" size={16} color={PA.ink}/></Pressable></View>{(def?.options.length??0)>8?<TextInput style={s.search} value={query} onChangeText={setQuery} placeholder="Rechercher…" placeholderTextColor="#9999a7"/>:null}<FlatList data={items} keyExtractor={x=>x.value} contentContainerStyle={{padding:16}} keyboardShouldPersistTaps="handled" keyboardDismissMode="interactive" automaticallyAdjustKeyboardInsets renderItem={({item})=>{const active=def?.type==='MULTISELECT'?selected.includes(item.value):value===item.value;return <Pressable style={[s.option,active&&s.optionActive]} onPress={()=>choose(item.value)}><Text style={[s.optionText,active&&s.optionTextActive]}>{item.label}</Text>{active?<AppIcon name="check" size={13}/>:null}</Pressable>}}/>{def?.type==='MULTISELECT'?<View style={s.modalBottom}><Pressable style={s.primary} onPress={close}><Text style={s.primaryText}>Terminer</Text></Pressable></View>:null}</SafeAreaView></Modal>}

